    'International student': ['learner', 'B', 'Student', ['Compliance notices acted on in time', 'Orientation tasks done', 'Support questions routed to the right office first time'], ['Gets a full-time enrolment reminder', 'Follows a hand-off to the international office', 'Completes orientation tasks', 'Finds housing and transit']],
    'Student athlete': ['learner', 'B', 'Student', ['Eligibility checks clear', 'Travel conflicts flagged early', 'Study hours logged'], ['Sees travel days against assignment deadlines', 'Shares a progress summary with academic support, by choice', 'Plans make-up work', 'Checks eligibility status']],
    'Student worker': ['learner', 'BG', 'Student', ['Shifts and classes without conflict', 'Workload within plan', 'Payroll hand-offs completed'], ['Sees shifts beside classes', 'Moves a study block around a shift', 'Follows the payroll hand-off', 'Checks hours against the plan']],
    'Student parent/caregiver': ['learner', 'BG', 'Student', ['Flexible-plan adherence', 'Resource hand-offs completed', 'Missed deadlines avoided'], ['Plans study time around childcare', 'Finds the childcare resource office', 'Gets an extension request routed', 'Shares a summary with a support coordinator']],
